package com.example.carlauncher.model;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import java.util.Arrays;
import java.util.Collection;
import static org.junit.Assert.assertEquals;

/** Design section 6.2: rounding precedes range validation; speed errors precede gear errors. */
@RunWith(Parameterized.class)
public class VehicleDesignBoundaryTest {
    @Parameterized.Parameters(name = "{index}: speed={0}, gear={1}, validity={2}")
    public static Collection<Object[]> cases() {
        return Arrays.asList(new Object[][] {
                {-0.5f, Gear.D, DataValidity.VALID},
                {Math.nextDown(-0.5f), Gear.D, DataValidity.INVALID_SPEED},
                {0f, Gear.P, DataValidity.VALID},
                {200f, Gear.D, DataValidity.VALID},
                {Math.nextDown(200.5f), Gear.D, DataValidity.VALID},
                {200.5f, Gear.D, DataValidity.INVALID_SPEED},
                {Float.MAX_VALUE, Gear.D, DataValidity.INVALID_SPEED},
                {-Float.MAX_VALUE, Gear.D, DataValidity.INVALID_SPEED},
                {Float.NaN, null, DataValidity.INVALID_SPEED},
                {Float.POSITIVE_INFINITY, null, DataValidity.INVALID_SPEED},
                {0f, null, DataValidity.INCOMPLETE}
        });
    }

    private final float speed;
    private final Gear gear;
    private final DataValidity expected;

    public VehicleDesignBoundaryTest(float speed, Gear gear, DataValidity expected) {
        this.speed = speed;
        this.gear = gear;
        this.expected = expected;
    }

    @Test public void validate_respectsRoundedBoundaryAndErrorPrecedence() {
        assertEquals(expected, VehicleStateValidator.validate(speed, gear));
    }
}

package com.example.carlauncher.model;

import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Design section 6.1: snapshot isolation and wire compatibility. */
public class VehicleSnapshotDesignTest {
    @Test public void reusedBuilder_doesNotMutatePublishedSnapshot() throws Exception {
        VehicleState.Builder builder = new VehicleState.Builder().setSequence(1)
                .setVehSpeedKph(10).setGear(Gear.D).setSoc(70).setDoorLock(true);
        VehicleState first = builder.build();
        String original = first.toJson();
        VehicleState second = builder.setSequence(2).setVehSpeedKph(0)
                .setGear(Gear.P).setSoc(30).setDoorLock(false).build();
        assertNotSame(first, second);
        assertEquals(original, first.toJson());
        assertEquals(2, second.getSequence());
        assertEquals(0, second.getVehSpeedKph());
        assertEquals(Gear.P, second.getGear());
        assertEquals(Boolean.FALSE, second.getDoorLock());
    }

    @Test public void injectedInvalidValues_preserveRawSpeedRpmAndBatteryButClampSoc() throws Exception {
        JSONObject json = new JSONObject(new VehicleState.Builder().setVehSpeedKph(255)
                .setEngRpm(9999).setSoc(150).setEvBatteryLevel(150f)
                .setEngineCoolantTemp(-999f).setValidity(DataValidity.INVALID_SPEED)
                .build().toJson());
        assertEquals(255, json.getInt("speedKph"));
        assertEquals(9999, json.getInt("rpm"));
        assertEquals(100, json.getInt("soc"));
        assertEquals(150, json.getDouble("evBatteryLevel"), 0);
        assertEquals(-999, json.getDouble("engineCoolantTemp"), 0);
        assertEquals(1, json.getInt("validity"));
    }

    @Test public void explicitNullOptionals_areOmittedRatherThanWrittenAsFalseOrZero() throws Exception {
        JSONObject json = new JSONObject(new VehicleState.Builder().setDoorLock(null)
                .setBeltWarning(null).setHeadlightsState(null).build().toJson());
        for (String key : new String[]{"doorLock", "beltWarning", "headlightsState",
                "highBeamLightsState", "engineCoolantTemp", "evBatteryLevel", "dataStatus"}) {
            assertFalse(key, json.has(key));
        }
        assertTrue(json.has("parkingBrake"));
        assertTrue(json.has("validity"));
    }

    @Test public void sequenceAndTimestamp_preserveLongPrecisionOnWire() throws Exception {
        long sequence = 9007199254740993L;
        JSONObject json = new JSONObject(new VehicleState.Builder().setSequence(sequence)
                .setTimestampMs(Long.MAX_VALUE).setSoc(0).build().toJson());
        assertEquals(sequence, json.getLong("seq"));
        assertEquals(Long.MAX_VALUE, json.getLong("timestampMs"));
        assertEquals(0, json.getInt("soc"));
        assertEquals(100, new VehicleState.Builder().setSoc(100).build().getSoc());
    }
}

package com.example.carlauncher.data.mock;

import com.example.carlauncher.data.DataSourceStatus;
import com.example.carlauncher.data.DataStatus;
import com.example.carlauncher.data.SourceType;
import com.example.carlauncher.data.VehicleDataSource;
import com.example.carlauncher.data.VehicleDataSourceFactory;
import com.example.carlauncher.model.DataValidity;
import com.example.carlauncher.model.Gear;
import com.example.carlauncher.model.VehicleState;

import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * MockVehicleDataSource 的确定性测试：通过注入可控调度器，同步驱动
 * 100ms 定时生成逻辑，覆盖正常/非法/静默/恢复四段模拟周期。
 */
public class MockVehicleDataSourceTest {

    /** 可控调度器：捕获 scheduleWithFixedDelay 的任务，由测试手动 tick。 */
    private static final class ControllableScheduler {
        private final AtomicReference<Runnable> task = new AtomicReference<>();

        private final ScheduledExecutorService executor =
                (ScheduledExecutorService) Proxy.newProxyInstance(
                        ControllableScheduler.class.getClassLoader(),
                        new Class<?>[]{ScheduledExecutorService.class},
                        (proxy, method, args) -> {
                            switch (method.getName()) {
                                case "scheduleWithFixedDelay":
                                    task.set((Runnable) args[0]);
                                    return null;
                                case "schedule":
                                case "scheduleAtFixedRate":
                                    return null;
                                case "execute":
                                    ((Runnable) args[0]).run();
                                    return null;
                                case "shutdownNow":
                                    return Collections.emptyList();
                                case "shutdown":
                                    return null;
                                case "isShutdown":
                                case "isTerminated":
                                    return false;
                                case "awaitTermination":
                                    return false;
                                default: {
                                    Class<?> returnType = method.getReturnType();
                                    if (returnType == boolean.class) {
                                        return false;
                                    }
                                    if (returnType == int.class) {
                                        return 0;
                                    }
                                    if (returnType == long.class) {
                                        return 0L;
                                    }
                                    if (List.class.isAssignableFrom(returnType)) {
                                        return Collections.emptyList();
                                    }
                                    if (ScheduledFuture.class.isAssignableFrom(returnType)) {
                                        return null;
                                    }
                                    return null;
                                }
                            }
                        });

        ScheduledExecutorService scheduler() {
            return executor;
        }

        void tick() {
            Runnable runnable = task.get();
            if (runnable == null) {
                throw new IllegalStateException("start() 尚未调度任务");
            }
            runnable.run();
        }
    }

    /** 记录回调的监听器。 */
    private static final class RecordingListener implements VehicleDataSource.Listener {
        final List<VehicleState> states = new ArrayList<>();
        final List<DataSourceStatus> statuses = new ArrayList<>();
        final List<Exception> errors = new ArrayList<>();

        @Override
        public void onStateChanged(VehicleState state) {
            states.add(state);
        }

        @Override
        public void onSourceStatusChanged(DataSourceStatus status) {
            statuses.add(status);
        }

        @Override
        public void onError(Exception exception) {
            errors.add(exception);
        }
    }

    @Test
    public void start_reportsConnected_andGeneratesNormalFrames() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();

        source.start(listener);

        assertTrue(source.isRunning());
        assertEquals(Collections.singletonList(DataSourceStatus.CONNECTED),
                listener.statuses);

        scheduler.tick();

        assertEquals(1, listener.states.size());
        VehicleState state = listener.states.get(0);
        assertEquals(1L, state.getSequence());
        assertEquals(2, state.getVehSpeedKph());   // 0 -> +2
        assertEquals(Gear.D, state.getGear());
        assertEquals(DataValidity.VALID, state.getValidity());
        assertEquals(DataStatus.NORMAL, state.getDataStatus());
        assertEquals(70, state.getSoc());
        assertEquals(850, state.getEngRpm());      // 800 + 2 * 25
        assertEquals(0, listener.errors.size());
    }

    @Test
    public void ticks_driveSpeedCycle_betweenZeroAndHundred() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);

        // 第 50 帧：加速到 100 km/h 峰值
        for (int i = 0; i < 50; i++) {
            scheduler.tick();
        }
        VehicleState peak = listener.states.get(49);
        assertEquals(100, peak.getVehSpeedKph());
        assertEquals(Gear.D, peak.getGear());
        assertEquals(3300, peak.getEngRpm());      // 800 + 100 * 25

        // 再走 50 帧：回到 0 km/h（P 档、怠速 800）
        for (int i = 0; i < 50; i++) {
            scheduler.tick();
        }
        VehicleState valley = listener.states.get(99);
        assertEquals(0, valley.getVehSpeedKph());
        assertEquals(Gear.P, valley.getGear());
        assertEquals(800, valley.getEngRpm());
    }

    @Test
    public void invalidWindow_emitsInvalidSpeedFrames() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);

        // 第 600 帧进入 600-700 非法数据窗口
        for (int i = 0; i < 600; i++) {
            scheduler.tick();
        }
        VehicleState invalid = listener.states.get(599);
        assertEquals(600L, invalid.getSequence());
        assertEquals(255, invalid.getVehSpeedKph()); // 超出 200 上限
        assertEquals(9999, invalid.getEngRpm());
        assertEquals(DataValidity.INVALID_SPEED, invalid.getValidity());
        assertEquals(DataStatus.INVALID, invalid.getDataStatus());
    }

    @Test
    public void silentWindow_reportsNoData_thenResumesConnected() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        listener.statuses.clear();

        // 推进到第 699 帧（seq=699，仍在非法数据窗口内，无状态变更回调）
        for (int i = 0; i < 699; i++) {
            scheduler.tick();
        }
        int statesBeforeSilence = listener.states.size();
        assertEquals(0, listener.statuses.size());

        // 第 700 帧进入静默窗口：上报 NO_DATA，且不产生状态帧
        scheduler.tick();
        assertEquals(Collections.singletonList(DataSourceStatus.NO_DATA),
                listener.statuses);
        assertEquals(statesBeforeSilence, listener.states.size());

        // 静默窗口（seq 701..999）内不再产生任何回调
        for (int i = 0; i < 299; i++) {
            scheduler.tick();
        }
        assertEquals(statesBeforeSilence, listener.states.size());
        assertEquals(1, listener.statuses.size());

        // seq=1000 恢复正常：上报 CONNECTED 并继续产生帧
        scheduler.tick();
        assertEquals(2, listener.statuses.size());
        assertEquals(DataSourceStatus.CONNECTED,
                listener.statuses.get(listener.statuses.size() - 1));
        assertEquals(statesBeforeSilence + 1, listener.states.size());
        VehicleState resumed = listener.states.get(listener.states.size() - 1);
        assertEquals(1000L, resumed.getSequence());
        assertEquals(DataValidity.VALID, resumed.getValidity());
    }

    @Test
    public void start_whileAlreadyRunning_ignoresSecondListener() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener first = new RecordingListener();
        RecordingListener second = new RecordingListener();

        source.start(first);
        source.start(second);
        assertTrue(source.isRunning());
        assertEquals(0, second.states.size());
        assertEquals(0, second.statuses.size());

        scheduler.tick();
        assertEquals(1, first.states.size());
        assertEquals(0, second.states.size());
    }

    @Test
    public void stop_reportsStopped_andClearsRunningState() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        listener.statuses.clear();

        source.stop();

        assertFalse(source.isRunning());
        assertEquals(Collections.singletonList(DataSourceStatus.STOPPED),
                listener.statuses);
    }

    @Test
    public void factory_mockSourceType_createsMockDataSource() {
        VehicleDataSource dataSource = VehicleDataSourceFactory.create(
                null, SourceType.MOCK);
        assertSame(MockVehicleDataSource.class, dataSource.getClass());
        assertFalse(dataSource.isRunning());
    }

    @Test
    public void invalidWindow_lastFramePreservesRawBatteryAndClampsSoc() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        try {
            source.start(listener);
            for (int i = 0; i < 699; i++) scheduler.tick();
            VehicleState last = listener.states.get(698);
            assertEquals(699L, last.getSequence());
            assertEquals(100, last.getSoc());
            assertEquals(Float.valueOf(150f), last.getEvBatteryLevel());
            assertEquals(Float.valueOf(-999f), last.getEngineCoolantTemp());
            assertEquals(DataStatus.INVALID, last.getDataStatus());
        } finally {
            source.stop();
        }
    }

    @Test
    public void stop_twiceEmitsStoppedOnceAndDropsAlreadyQueuedNormalFrame() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        scheduler.tick();
        source.stop();
        source.stop();
        scheduler.tick(); // An executor task captured before shutdown can still be in flight.
        assertEquals(1, listener.states.size());
        assertEquals(java.util.Arrays.asList(DataSourceStatus.CONNECTED, DataSourceStatus.STOPPED),
                listener.statuses);
        assertFalse(source.isRunning());
    }

    @Test
    public void stop_beforeQueuedSilenceTransitionDoesNotDereferenceClearedListener() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        for (int i = 0; i < 699; i++) scheduler.tick();
        source.stop();
        scheduler.tick(); // seq=700: same cancellation contract as an ordinary queued frame.
        assertEquals(699, listener.states.size());
        assertEquals(java.util.Arrays.asList(DataSourceStatus.CONNECTED, DataSourceStatus.STOPPED),
                listener.statuses);
    }
}

package com.example.carlauncher;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.os.Looper;
import android.widget.TextView;

import androidx.lifecycle.Lifecycle;
import androidx.test.core.app.ActivityScenario;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;

import org.junit.Test;
import org.junit.runner.RunWith;
import androidx.test.platform.app.InstrumentationRegistry;

import static org.junit.Assert.assertEquals;

/**
 * BroadcastLabActivity 的 Instrumentation 测试：
 * 电源广播接收与 onStop 时的反注册。
 */
@RunWith(AndroidJUnit4.class)
public class BroadcastLabActivityTest {

    private static void idleMainLooper() {
        InstrumentationRegistry.getInstrumentation().waitForIdleSync();
    }

    @Test
    public void powerBroadcasts_updateStatusText() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            scenario.onActivity(activity -> {
                assertEquals("Waiting for power broadcast",
                        text(activity));
            });

            scenario.onActivity(activity -> {
                dispatchPowerAction(activity, Intent.ACTION_POWER_CONNECTED);
                assertEquals("Power connected", text(activity));
                dispatchPowerAction(activity, Intent.ACTION_POWER_DISCONNECTED);
                assertEquals("Power disconnected", text(activity));
            });
        }
    }

    @Test
    public void receiver_isUnregisteredAfterStop() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            scenario.onActivity(activity -> assertEquals(true, receiverRegistered(activity)));
            scenario.moveToState(Lifecycle.State.CREATED);
            scenario.onActivity(activity -> assertEquals(false, receiverRegistered(activity)));
        }
    }

    private static void dispatchPowerAction(BroadcastLabActivity activity, String action) {
        try {
            java.lang.reflect.Field field = BroadcastLabActivity.class
                    .getDeclaredField("powerReceiver");
            field.setAccessible(true);
            ((BroadcastReceiver) field.get(activity)).onReceive(activity, new Intent(action));
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError(exception);
        }
    }

    @Test
    public void sameInstanceReturningToForeground_registersReceiverAgain() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            java.util.concurrent.atomic.AtomicReference<BroadcastLabActivity> original =
                    new java.util.concurrent.atomic.AtomicReference<>();
            scenario.onActivity(original::set);
            scenario.moveToState(Lifecycle.State.CREATED);
            scenario.moveToState(Lifecycle.State.RESUMED);
            scenario.onActivity(activity -> {
                org.junit.Assert.assertSame(original.get(), activity);
                org.junit.Assert.assertTrue("onStart must register after the previous onStop",
                        receiverRegistered(activity));
                dispatchPowerAction(activity, Intent.ACTION_POWER_CONNECTED);
                assertEquals("Power connected", text(activity));
            });
        }
    }

    private static boolean receiverRegistered(BroadcastLabActivity activity) {
        try {
            java.lang.reflect.Field field = BroadcastLabActivity.class
                    .getDeclaredField("receiverRegistered");
            field.setAccessible(true);
            return field.getBoolean(activity);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError(exception);
        }
    }

    private static String text(BroadcastLabActivity activity) {
        return ((TextView) activity.findViewById(R.id.broadcastStatusText))
                .getText().toString();
    }
}

package com.example.carlauncher;

import android.os.Looper;
import android.view.View;
import android.widget.TextView;

import androidx.fragment.app.Fragment;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;

import org.junit.Test;
import org.junit.runner.RunWith;
import androidx.test.platform.app.InstrumentationRegistry;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * FragmentLabActivity（单栏布局）的 Instrumentation 测试：
 * 菜单导航到详情、防抖与重复选择忽略、返回栈弹出。
 */
@RunWith(AndroidJUnit4.class)
public class FragmentLabActivityTest {

    private static void idleMainLooper() {
        InstrumentationRegistry.getInstrumentation().waitForIdleSync();
    }

    @Test
    public void recreate_keepsSelectedDetailAndBackStackWithoutAddingInitialFragments() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            scenario.onActivity(activity -> {
                activity.onSettingSelected("Network");
                activity.getSupportFragmentManager().executePendingTransactions();
            });
            java.util.concurrent.atomic.AtomicInteger backStack = new java.util.concurrent.atomic.AtomicInteger();
            scenario.onActivity(activity -> backStack.set(
                    activity.getSupportFragmentManager().getBackStackEntryCount()));
            scenario.recreate();
            scenario.onActivity(activity -> {
                assertEquals("Network Detail", detailTitle(detailFragment(activity)));
                assertEquals(backStack.get(),
                        activity.getSupportFragmentManager().getBackStackEntryCount());
                assertEquals(1, activity.getSupportFragmentManager().getFragments().stream()
                        .filter(fragment -> "settings_detail".equals(fragment.getTag())).count());
            });
        }
    }

    private static Fragment detailFragment(FragmentLabActivity activity) {
        return activity.getSupportFragmentManager()
                .findFragmentByTag("settings_detail");
    }

    private static String detailTitle(Fragment detail) {
        return ((TextView) detail.getView().findViewById(R.id.detailTitleText))
                .getText().toString();
    }

    @Test
    public void launch_showsMenuFragment_inSinglePane() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            idleMainLooper();
            scenario.onActivity(activity -> {
                Fragment menu = activity.getSupportFragmentManager()
                        .findFragmentByTag(SettingsMenuFragment.TAG);
                assertNotNull(menu);
                if (activity.findViewById(R.id.detail_container) == null) {
                    assertNull(detailFragment(activity));
                } else {
                    assertNotNull(detailFragment(activity));
                }
            });
        }
    }

    @Test
    public void menuButton_navigatesToDetailWithBackButton() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            idleMainLooper();
            scenario.onActivity(activity ->
                    activity.findViewById(R.id.displaySettingsButton).performClick());
            idleMainLooper();

            scenario.onActivity(activity -> {
                Fragment detail = detailFragment(activity);
                assertNotNull(detail);
                assertEquals("Display Detail", detailTitle(detail));
                int expectedVisibility = activity.findViewById(R.id.detail_container) == null
                        ? View.VISIBLE : View.GONE;
                assertEquals(expectedVisibility,
                        detail.getView().findViewById(R.id.detailBackButton).getVisibility());
            });
        }
    }

    @Test
    public void rapidSecondSelection_isDebounced() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            idleMainLooper();
            scenario.onActivity(activity -> {
                activity.onSettingSelected("Network");
                // 同一时刻再次选择应被 500ms 防抖忽略
                activity.onSettingSelected("About");
            });
            idleMainLooper();

            scenario.onActivity(activity ->
                    assertEquals("Network Detail", detailTitle(detailFragment(activity))));

        }
    }

    @Test
    public void duplicateSelection_isIgnored() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            idleMainLooper();
            scenario.onActivity(activity -> activity.onSettingSelected("Network"));
            idleMainLooper();

            // 重复选择不应改变当前详情。
            scenario.onActivity(activity -> activity.onSettingSelected("Network"));
            idleMainLooper();

            scenario.onActivity(activity ->
                    assertEquals("Network Detail", detailTitle(detailFragment(activity))));
        }
    }

    @Test
    public void detailBackButton_popsBackToMenu() {
        try (ActivityScenario<FragmentLabActivity> scenario =
                     ActivityScenario.launch(FragmentLabActivity.class)) {
            idleMainLooper();
            scenario.onActivity(activity -> activity.onSettingSelected("Display"));
            idleMainLooper();

            scenario.onActivity(activity -> {
                Fragment detail = detailFragment(activity);
                assertNotNull(detail);
                View backButton = detail.getView().findViewById(R.id.detailBackButton);
                if (backButton.getVisibility() == View.VISIBLE) {
                    backButton.performClick();
                }
            });
            idleMainLooper();

            scenario.onActivity(activity -> {
                assertNotNull(activity.getSupportFragmentManager()
                        .findFragmentByTag(SettingsMenuFragment.TAG));
                if (activity.findViewById(R.id.detail_container) == null) {
                    assertNull(detailFragment(activity));
                } else {
                    assertNotNull(detailFragment(activity));
                }
            });
        }
    }
}

package com.example.carlauncher;

import android.widget.Button;
import android.widget.TextView;

import androidx.lifecycle.ViewModelProvider;
import androidx.test.core.app.ActivityScenario;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;

import com.example.carlauncher.data.DataSourceStatus;
import com.example.carlauncher.model.DataValidity;
import com.example.carlauncher.model.Gear;
import com.example.carlauncher.model.TurnSignal;
import com.example.carlauncher.model.VehicleState;
import com.example.carlauncher.model.WarningState;
import com.example.carlauncher.testing.StubVehicleSendService;
import com.example.carlauncher.ui.CockpitViewModel;

import org.junit.Test;
import org.junit.runner.RunWith;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * MainActivity 的 Instrumentation 集成测试：初始无数据 UI、服务快照驱动的
 * 仪表渲染，以及快捷入口按钮的跳转目标。不点击“START RECEIVE”，避免触发
 * 真实前台 Service / TCP 副作用。
 */
@RunWith(AndroidJUnit4.class)
public class MainActivityTest {

    /**
     * 测试用 Activity 子类：Instrumentation 环境没有真实 VehicleSendService，
     * 若允许绑定会以 null binder 回调 onServiceConnected 导致崩溃。
     * 这里让 bindService 直接失败，等价于“服务未运行”的真实场景。
     * 测试活动未声明在 manifest 中，因此用 ActivityController 直接驱动。
     */
    @Test
    public void launch_showsInitialNoDataUi() {
        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> {
                assertEquals("-- km/h", text(activity, R.id.speedText));
                assertEquals("-", text(activity, R.id.gearText));
                assertEquals("-- rpm", text(activity, R.id.rpmText));
                assertEquals("-- %", text(activity, R.id.batteryText));
                assertEquals("NO DATA", text(activity, R.id.warningText));
                assertEquals("INVALID", text(activity, R.id.validityText));
                assertEquals("Seq --", text(activity, R.id.sequenceText));
                assertEquals("Waiting for vehicle data", text(activity, R.id.lastUpdateText));
                assertEquals("SERVICE UNBOUND", text(activity, R.id.connectionStatusText));
                assertEquals("START RECEIVE", text(activity, R.id.connectButton));
                Button connectButton = activity.findViewById(R.id.connectButton);
                assertTrue(connectButton.isEnabled());
                assertEquals("SOME/IP: STOPPED", text(activity, R.id.transportStatusText));
            });
        }
    }

    @Test
    public void attachedServiceWithVehicleState_rendersFullDashboard() {
        VehicleState vehicleState = new VehicleState.Builder()
                .setVersion(1)
                .setSequence(12L)
                .setVehSpeedKph(66)
                .setEngRpm(2450)
                .setGear(Gear.D)
                .setSoc(70)
                .setTurnSignal(TurnSignal.LEFT)
                .setParkingBrake(true)
                .setWarning(WarningState.CRITICAL)
                .setValidity(DataValidity.VALID)
                .setDoorLock(true)
                .setBeltWarning(true)
                .setEngineCoolantTemp(90.5f)
                .setEvBatteryLevel(80.0f)
                .build();

        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> new ViewModelProvider(activity)
                    .get(CockpitViewModel.class)
                    .attachService(new StubVehicleSendService()
                            .withLatestState(vehicleState)
                            .withSourceStatus(DataSourceStatus.CONNECTED)
                            .withSomeipAvailable(true, 0).withSomeipResponse(true, 0, 1)
                            .withValidity(DataValidity.VALID)));
            InstrumentationRegistry.getInstrumentation().waitForIdleSync();
            scenario.onActivity(activity -> {
                assertEquals("66 km/h", text(activity, R.id.speedText));
                assertEquals("D", text(activity, R.id.gearText));
                assertEquals("2450 rpm", text(activity, R.id.rpmText));
                assertEquals("70%", text(activity, R.id.batteryText));
                assertEquals("80 %", text(activity, R.id.evBatteryText));
                assertEquals("91 °C", text(activity, R.id.coolantTempText));
                assertEquals("LEFT", text(activity, R.id.turnSignalText));
                assertEquals("ON", text(activity, R.id.parkingBrakeText));
                assertEquals("LOCKED", text(activity, R.id.doorLockText));
                assertEquals("CRITICAL", text(activity, R.id.warningText));
                assertEquals("VALID", text(activity, R.id.validityText));
                assertEquals("Seq 12", text(activity, R.id.sequenceText));
                assertEquals("Updated · Seq 12", text(activity, R.id.lastUpdateText));
                assertEquals("SOME/IP ONLINE", text(activity, R.id.connectionStatusText));
                assertEquals("STOP RECEIVE", text(activity, R.id.connectButton));
                assertEquals("CONNECTED", text(activity, R.id.sourceStatusText));
                assertEquals("SOME/IP: AVAILABLE | ONLINE | EVENT 0x8001", text(activity, R.id.transportStatusText));
            });
        }
    }

    @Test
    public void attachedServiceWithNullState_rendersNoDataPlaceholders() {
        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> new ViewModelProvider(activity)
                    .get(CockpitViewModel.class)
                    .attachService(new StubVehicleSendService()
                            .withLatestState(null)
                            .withSourceStatus(DataSourceStatus.CONNECTED)
                            .withSomeipAvailable(true, 0).withSomeipResponse(true, 0, 1)
                            .withValidity(DataValidity.VALID)));
            InstrumentationRegistry.getInstrumentation().waitForIdleSync();
            scenario.onActivity(activity -> {
                assertEquals("SOME/IP ONLINE", text(activity, R.id.connectionStatusText));
                assertEquals("-- km/h", text(activity, R.id.speedText));
                assertEquals("NO DATA", text(activity, R.id.warningText));
            });
        }
    }

    private static String text(MainActivity activity, int viewId) {
        TextView view = activity.findViewById(viewId);
        return view.getText().toString();
    }

    @Test
    public void invalidSnapshot_displaysRawValuesAlongsideInvalidity() {
        VehicleState state = new VehicleState.Builder().setVehSpeedKph(255).setEngRpm(9999)
                .setSoc(150).setEvBatteryLevel(150f).setEngineCoolantTemp(-999f)
                .setValidity(DataValidity.INVALID_SPEED).build();
        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> {
                new ViewModelProvider(activity).get(CockpitViewModel.class)
                        .attachService(new StubVehicleSendService().withLatestState(state)
                                .withSomeipAvailable(true, 0).withSomeipResponse(true, 0, 1)
                                .withValidity(DataValidity.INVALID_SPEED));
                assertEquals("255 km/h", text(activity, R.id.speedText));
                assertEquals("9999 rpm", text(activity, R.id.rpmText));
                assertEquals("100%", text(activity, R.id.batteryText));
                assertEquals("150 %", text(activity, R.id.evBatteryText));
                assertEquals("-999 °C", text(activity, R.id.coolantTempText));
                assertEquals("INVALID_SPEED", text(activity, R.id.validityText));
                assertEquals("SOME/IP ONLINE / INVALID DATA", text(activity, R.id.connectionStatusText));
            });
        }
    }

    @Test
    public void nextSnapshotWithMissingOptionals_clearsPreviouslyDisplayedValues() {
        StubVehicleSendService service = new StubVehicleSendService()
                .withLatestState(new VehicleState.Builder().setDoorLock(true)
                        .setEngineCoolantTemp(90f).setEvBatteryLevel(70f).build());
        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> {
                CockpitViewModel model = new ViewModelProvider(activity).get(CockpitViewModel.class);
                model.attachService(service);
                assertEquals("LOCKED", text(activity, R.id.doorLockText));
                assertEquals("90 °C", text(activity, R.id.coolantTempText));
                assertEquals("70 %", text(activity, R.id.evBatteryText));
                service.withLatestState(new VehicleState.Builder().setDoorLock(null).build());
                model.refresh();
                assertEquals("--", text(activity, R.id.doorLockText));
                assertEquals("-- °C", text(activity, R.id.coolantTempText));
                assertEquals("-- %", text(activity, R.id.evBatteryText));
            });
        }
    }

    @Test
    public void someipFaultsRemainVisibleUntilEventRecovery() {
        StubVehicleSendService service = new StubVehicleSendService()
                .withSomeipAvailable(true, 0);
        try (ActivityScenario<MainActivity> scenario = ActivityScenario.launch(MainActivity.class)) {
            scenario.onActivity(activity -> {
                CockpitViewModel model = new ViewModelProvider(activity).get(CockpitViewModel.class);
                model.attachService(service);
                assertEquals("SOME/IP WAITING EVENT", text(activity, R.id.connectionStatusText));
                assertEquals("STOP RECEIVE", text(activity, R.id.connectButton));
                assertTrue(activity.findViewById(R.id.connectButton).isEnabled());

                service.withSomeipResponse(false, 1, 10);
                model.refresh();
                assertEquals("SOME/IP RESPONSE_ERROR", text(activity, R.id.connectionStatusText));
                assertTrue(text(activity, R.id.transportStatusText).contains("RESPONSE_ERROR"));

                service.checkSomeipTimeout(3010);
                model.refresh();
                assertEquals("SOME/IP EVENT TIMEOUT", text(activity, R.id.connectionStatusText));
                assertEquals("STOP RECEIVE", text(activity, R.id.connectButton));

                service.withSomeipResponse(true, 0, 3020);
                model.refresh();
                assertEquals("SOME/IP ONLINE", text(activity, R.id.connectionStatusText));
            });
        }
    }
}

package com.example.carlauncher.data.local;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteConstraintException;
import android.database.sqlite.SQLiteDatabase;

import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;

import org.junit.Test;
import org.junit.Before;
import org.junit.After;
import org.junit.runner.RunWith;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * LabDatabaseHelper 的 Instrumentation 真实 SQLite 行为测试：
 * 建表、增删改查、UNIQUE 约束与 v1→v2 升级迁移。
 */
@RunWith(AndroidJUnit4.class)
public class LabDatabaseHelperTest {

    private static final String TABLE = LabDatabaseContract.LabRecordEntry.TABLE_NAME;

    private Context context() {
        return ApplicationProvider.getApplicationContext();
    }

    @Before
    public void deleteDatabaseBeforeTest() {
        context().deleteDatabase(LabDatabaseHelper.DATABASE_NAME);
    }

    @After
    public void deleteDatabaseAfterTest() {
        context().deleteDatabase(LabDatabaseHelper.DATABASE_NAME);
    }

    @Test
    public void getWritableDatabase_createsSchemaWithVersionTwo() {
        LabDatabaseHelper helper = new LabDatabaseHelper(context());
        SQLiteDatabase database = helper.getWritableDatabase();

        assertEquals(LabDatabaseHelper.DATABASE_VERSION, database.getVersion());

        try (Cursor cursor = database.rawQuery(
                "SELECT count(*) FROM sqlite_master WHERE type='table' AND name=?",
                new String[]{TABLE})) {
            assertTrue(cursor.moveToFirst());
            assertEquals(1, cursor.getInt(0));
        }
        assertTrue("v2 应包含 note 列", hasColumn(database, "note"));
        helper.close();
    }

    @Test
    public void insert_thenQuery_roundTripsRecord() {
        LabDatabaseHelper helper = new LabDatabaseHelper(context());
        SQLiteDatabase database = helper.getWritableDatabase();

        long rowId = insertRecord(database, "speed", "80", "lab-note");
        assertTrue(rowId > 0);

        try (Cursor cursor = database.query(
                TABLE,
                null,
                LabDatabaseContract.LabRecordEntry.COLUMN_NAME + "=?",
                new String[]{"speed"},
                null,
                null,
                null)) {
            assertTrue(cursor.moveToFirst());
            assertEquals("speed", cursor.getString(
                    cursor.getColumnIndexOrThrow(
                            LabDatabaseContract.LabRecordEntry.COLUMN_NAME)));
            assertEquals("80", cursor.getString(
                    cursor.getColumnIndexOrThrow(
                            LabDatabaseContract.LabRecordEntry.COLUMN_VALUE)));
            assertEquals("lab-note", cursor.getString(
                    cursor.getColumnIndexOrThrow(
                            LabDatabaseContract.LabRecordEntry.COLUMN_NOTE)));
            assertEquals(1, cursor.getCount());
        }
        helper.close();
    }

    @Test
    public void insert_duplicateUniqueName_throwsConstraintException() {
        LabDatabaseHelper helper = new LabDatabaseHelper(context());
        SQLiteDatabase database = helper.getWritableDatabase();

        insertRecord(database, "dup", "1", "");
        try {
            insertRecord(database, "dup", "2", "");
            fail("name 列 UNIQUE 约束应拒绝重复插入");
        } catch (SQLiteConstraintException expected) {
            // 期望的约束冲突
        }
        helper.close();
    }

    @Test
    public void updateAndDelete_affectMatchingRows() {
        LabDatabaseHelper helper = new LabDatabaseHelper(context());
        SQLiteDatabase database = helper.getWritableDatabase();

        insertRecord(database, "gear", "P", "");
        insertRecord(database, "other", "x", "");

        ContentValues update = new ContentValues();
        update.put(LabDatabaseContract.LabRecordEntry.COLUMN_VALUE, "D");
        int updated = database.update(
                TABLE,
                update,
                LabDatabaseContract.LabRecordEntry.COLUMN_NAME + "=?",
                new String[]{"gear"});
        assertEquals(1, updated);

        int deleted = database.delete(
                TABLE,
                LabDatabaseContract.LabRecordEntry.COLUMN_NAME + "=?",
                new String[]{"other"});
        assertEquals(1, deleted);

        try (Cursor cursor = database.query(
                TABLE, null, null, null, null, null, null)) {
            assertEquals(1, cursor.getCount());
        }
        helper.close();
    }

    @Test
    public void upgrade_fromVersionOne_addsNoteColumn() {
        Context context = context();
        // 先手工创建 v1 结构（无 note 列）的数据库文件
        SQLiteDatabase v1 = context.openOrCreateDatabase(
                LabDatabaseHelper.DATABASE_NAME, Context.MODE_PRIVATE, null);
        v1.execSQL("CREATE TABLE " + TABLE + " ("
                + LabDatabaseContract.LabRecordEntry._ID
                + " INTEGER PRIMARY KEY AUTOINCREMENT, "
                + LabDatabaseContract.LabRecordEntry.COLUMN_NAME
                + " TEXT NOT NULL UNIQUE, "
                + LabDatabaseContract.LabRecordEntry.COLUMN_VALUE
                + " TEXT NOT NULL, "
                + LabDatabaseContract.LabRecordEntry.COLUMN_CREATED_AT
                + " INTEGER NOT NULL"
                + ")");
        v1.setVersion(1);
        v1.close();

        LabDatabaseHelper helper = new LabDatabaseHelper(context);
        SQLiteDatabase upgraded = helper.getWritableDatabase();

        assertEquals(LabDatabaseHelper.DATABASE_VERSION, upgraded.getVersion());
        assertTrue("v1→v2 升级应新增 note 列", hasColumn(upgraded, "note"));

        // 升级后的表应能写入 note（含 DEFAULT ''）
        long rowId = insertRecord(upgraded, "post-upgrade", "v", "");
        assertTrue(rowId > 0);
        helper.close();
    }

    private static long insertRecord(
            SQLiteDatabase database,
            String name,
            String value,
            String note
    ) {
        ContentValues values = new ContentValues();
        values.put(LabDatabaseContract.LabRecordEntry.COLUMN_NAME, name);
        values.put(LabDatabaseContract.LabRecordEntry.COLUMN_VALUE, value);
        values.put(LabDatabaseContract.LabRecordEntry.COLUMN_NOTE, note);
        values.put(LabDatabaseContract.LabRecordEntry.COLUMN_CREATED_AT,
                System.currentTimeMillis());
        return database.insertOrThrow(TABLE, null, values);
    }

    @Test
    public void upgrade_populatedVersionOnePreservesIdValueAndTimestampWithEmptyNote() {
        try (SQLiteDatabase database = SQLiteDatabase.create(null);
             LabDatabaseHelper helper = new LabDatabaseHelper(context())) {
            database.execSQL("CREATE TABLE " + TABLE + " ("
                    + "_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, "
                    + "value TEXT NOT NULL, created_at INTEGER NOT NULL)");
            database.execSQL("INSERT INTO " + TABLE
                    + " (_id,name,value,created_at) VALUES (41,'saved','80',1234)");
            helper.onUpgrade(database, 1, 2);
            try (Cursor cursor = database.rawQuery("SELECT * FROM " + TABLE, null)) {
                assertEquals(1, cursor.getCount());
                assertTrue(cursor.moveToFirst());
                assertEquals(41, cursor.getLong(cursor.getColumnIndexOrThrow("_id")));
                assertEquals("saved", cursor.getString(cursor.getColumnIndexOrThrow("name")));
                assertEquals("80", cursor.getString(cursor.getColumnIndexOrThrow("value")));
                assertEquals(1234, cursor.getLong(cursor.getColumnIndexOrThrow("created_at")));
                assertEquals("", cursor.getString(cursor.getColumnIndexOrThrow("note")));
            }
            assertTrue(insertRecord(database, "next", "81", "note") > 41);
        }
    }

    @Test
    public void schema_omittedNoteDefaultsEmptyButExplicitNullIsRejected() {
        try (SQLiteDatabase database = SQLiteDatabase.create(null);
             LabDatabaseHelper helper = new LabDatabaseHelper(context())) {
            helper.onCreate(database);
            database.execSQL("INSERT INTO " + TABLE
                    + " (name,value,created_at) VALUES ('default','v',1)");
            try (Cursor cursor = database.rawQuery("SELECT note FROM " + TABLE, null)) {
                assertTrue(cursor.moveToFirst());
                assertEquals("", cursor.getString(0));
            }
            try {
                database.execSQL("INSERT INTO " + TABLE
                        + " (name,value,created_at,note) VALUES ('null','v',2,NULL)");
                fail("Explicit NULL must not bypass the note NOT NULL contract");
            } catch (SQLiteConstraintException expected) {
                // The database, rather than UI validation, enforces the schema contract.
            }
        }
    }

    private static boolean hasColumn(SQLiteDatabase database, String column) {
        try (Cursor cursor = database.rawQuery(
                "PRAGMA table_info(" + TABLE + ")", null)) {
            int nameIndex = cursor.getColumnIndexOrThrow("name");
            while (cursor.moveToNext()) {
                if (column.equals(cursor.getString(nameIndex))) {
                    return true;
                }
            }
        }
        return false;
    }
}

