package com.example.carlauncher.model;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import java.util.Arrays;
import java.util.Collection;
import static org.junit.Assert.assertEquals;

/** Design section 6.2: rounding precedes range validation; speed errors precede gear errors. */
@RunWith(Parameterized.class)
public class VehicleDesignBoundaryTest {
    @Parameterized.Parameters(name = "{index}: speed={0}, gear={1}, validity={2}")
    public static Collection<Object[]> cases() {
        return Arrays.asList(new Object[][] {
                {-0.5f, Gear.D, DataValidity.VALID},
                {Math.nextDown(-0.5f), Gear.D, DataValidity.INVALID_SPEED},
                {0f, Gear.P, DataValidity.VALID},
                {200f, Gear.D, DataValidity.VALID},
                {Math.nextDown(200.5f), Gear.D, DataValidity.VALID},
                {200.5f, Gear.D, DataValidity.INVALID_SPEED},
                {Float.MAX_VALUE, Gear.D, DataValidity.INVALID_SPEED},
                {-Float.MAX_VALUE, Gear.D, DataValidity.INVALID_SPEED},
                {Float.NaN, null, DataValidity.INVALID_SPEED},
                {Float.POSITIVE_INFINITY, null, DataValidity.INVALID_SPEED},
                {0f, null, DataValidity.INCOMPLETE}
        });
    }

    private final float speed;
    private final Gear gear;
    private final DataValidity expected;

    public VehicleDesignBoundaryTest(float speed, Gear gear, DataValidity expected) {
        this.speed = speed;
        this.gear = gear;
        this.expected = expected;
    }

    @Test public void validate_respectsRoundedBoundaryAndErrorPrecedence() {
        assertEquals(expected, VehicleStateValidator.validate(speed, gear));
    }
}

package com.example.carlauncher.model;

import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Design section 6.1: snapshot isolation and wire compatibility. */
public class VehicleSnapshotDesignTest {
    @Test public void reusedBuilder_doesNotMutatePublishedSnapshot() throws Exception {
        VehicleState.Builder builder = new VehicleState.Builder().setSequence(1)
                .setVehSpeedKph(10).setGear(Gear.D).setSoc(70).setDoorLock(true);
        VehicleState first = builder.build();
        String original = first.toJson();
        VehicleState second = builder.setSequence(2).setVehSpeedKph(0)
                .setGear(Gear.P).setSoc(30).setDoorLock(false).build();
        assertNotSame(first, second);
        assertEquals(original, first.toJson());
        assertEquals(2, second.getSequence());
        assertEquals(0, second.getVehSpeedKph());
        assertEquals(Gear.P, second.getGear());
        assertEquals(Boolean.FALSE, second.getDoorLock());
    }

    @Test public void injectedInvalidValues_preserveRawSpeedRpmAndBatteryButClampSoc() throws Exception {
        JSONObject json = new JSONObject(new VehicleState.Builder().setVehSpeedKph(255)
                .setEngRpm(9999).setSoc(150).setEvBatteryLevel(150f)
                .setEngineCoolantTemp(-999f).setValidity(DataValidity.INVALID_SPEED)
                .build().toJson());
        assertEquals(255, json.getInt("speedKph"));
        assertEquals(9999, json.getInt("rpm"));
        assertEquals(100, json.getInt("soc"));
        assertEquals(150, json.getDouble("evBatteryLevel"), 0);
        assertEquals(-999, json.getDouble("engineCoolantTemp"), 0);
        assertEquals(1, json.getInt("validity"));
    }

    @Test public void explicitNullOptionals_areOmittedRatherThanWrittenAsFalseOrZero() throws Exception {
        JSONObject json = new JSONObject(new VehicleState.Builder().setDoorLock(null)
                .setBeltWarning(null).setHeadlightsState(null).build().toJson());
        for (String key : new String[]{"doorLock", "beltWarning", "headlightsState",
                "highBeamLightsState", "engineCoolantTemp", "evBatteryLevel", "dataStatus"}) {
            assertFalse(key, json.has(key));
        }
        assertTrue(json.has("parkingBrake"));
        assertTrue(json.has("validity"));
    }

    @Test public void sequenceAndTimestamp_preserveLongPrecisionOnWire() throws Exception {
        long sequence = 9007199254740993L;
        JSONObject json = new JSONObject(new VehicleState.Builder().setSequence(sequence)
                .setTimestampMs(Long.MAX_VALUE).setSoc(0).build().toJson());
        assertEquals(sequence, json.getLong("seq"));
        assertEquals(Long.MAX_VALUE, json.getLong("timestampMs"));
        assertEquals(0, json.getInt("soc"));
        assertEquals(100, new VehicleState.Builder().setSoc(100).build().getSoc());
    }
}

package com.example.carlauncher.data.mock;

import com.example.carlauncher.data.DataSourceStatus;
import com.example.carlauncher.data.DataStatus;
import com.example.carlauncher.data.SourceType;
import com.example.carlauncher.data.VehicleDataSource;
import com.example.carlauncher.data.VehicleDataSourceFactory;
import com.example.carlauncher.model.DataValidity;
import com.example.carlauncher.model.Gear;
import com.example.carlauncher.model.VehicleState;

import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * MockVehicleDataSource 的确定性测试：通过注入可控调度器，同步驱动
 * 100ms 定时生成逻辑，覆盖正常/非法/静默/恢复四段模拟周期。
 */
public class MockVehicleDataSourceTest {

    /** 可控调度器：捕获 scheduleWithFixedDelay 的任务，由测试手动 tick。 */
    private static final class ControllableScheduler {
        private final AtomicReference<Runnable> task = new AtomicReference<>();

        private final ScheduledExecutorService executor =
                (ScheduledExecutorService) Proxy.newProxyInstance(
                        ControllableScheduler.class.getClassLoader(),
                        new Class<?>[]{ScheduledExecutorService.class},
                        (proxy, method, args) -> {
                            switch (method.getName()) {
                                case "scheduleWithFixedDelay":
                                    task.set((Runnable) args[0]);
                                    return null;
                                case "schedule":
                                case "scheduleAtFixedRate":
                                    return null;
                                case "execute":
                                    ((Runnable) args[0]).run();
                                    return null;
                                case "shutdownNow":
                                    return Collections.emptyList();
                                case "shutdown":
                                    return null;
                                case "isShutdown":
                                case "isTerminated":
                                    return false;
                                case "awaitTermination":
                                    return false;
                                default: {
                                    Class<?> returnType = method.getReturnType();
                                    if (returnType == boolean.class) {
                                        return false;
                                    }
                                    if (returnType == int.class) {
                                        return 0;
                                    }
                                    if (returnType == long.class) {
                                        return 0L;
                                    }
                                    if (List.class.isAssignableFrom(returnType)) {
                                        return Collections.emptyList();
                                    }
                                    if (ScheduledFuture.class.isAssignableFrom(returnType)) {
                                        return null;
                                    }
                                    return null;
                                }
                            }
                        });

        ScheduledExecutorService scheduler() {
            return executor;
        }

        void tick() {
            Runnable runnable = task.get();
            if (runnable == null) {
                throw new IllegalStateException("start() 尚未调度任务");
            }
            runnable.run();
        }
    }

    /** 记录回调的监听器。 */
    private static final class RecordingListener implements VehicleDataSource.Listener {
        final List<VehicleState> states = new ArrayList<>();
        final List<DataSourceStatus> statuses = new ArrayList<>();
        final List<Exception> errors = new ArrayList<>();

        @Override
        public void onStateChanged(VehicleState state) {
            states.add(state);
        }

        @Override
        public void onSourceStatusChanged(DataSourceStatus status) {
            statuses.add(status);
        }

        @Override
        public void onError(Exception exception) {
            errors.add(exception);
        }
    }

    @Test
    public void start_reportsConnected_andGeneratesNormalFrames() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();

        source.start(listener);

        assertTrue(source.isRunning());
        assertEquals(Collections.singletonList(DataSourceStatus.CONNECTED),
                listener.statuses);

        scheduler.tick();

        assertEquals(1, listener.states.size());
        VehicleState state = listener.states.get(0);
        assertEquals(1L, state.getSequence());
        assertEquals(2, state.getVehSpeedKph());   // 0 -> +2
        assertEquals(Gear.D, state.getGear());
        assertEquals(DataValidity.VALID, state.getValidity());
        assertEquals(DataStatus.NORMAL, state.getDataStatus());
        assertEquals(70, state.getSoc());
        assertEquals(850, state.getEngRpm());      // 800 + 2 * 25
        assertEquals(0, listener.errors.size());
    }

    @Test
    public void ticks_driveSpeedCycle_betweenZeroAndHundred() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);

        // 第 50 帧：加速到 100 km/h 峰值
        for (int i = 0; i < 50; i++) {
            scheduler.tick();
        }
        VehicleState peak = listener.states.get(49);
        assertEquals(100, peak.getVehSpeedKph());
        assertEquals(Gear.D, peak.getGear());
        assertEquals(3300, peak.getEngRpm());      // 800 + 100 * 25

        // 再走 50 帧：回到 0 km/h（P 档、怠速 800）
        for (int i = 0; i < 50; i++) {
            scheduler.tick();
        }
        VehicleState valley = listener.states.get(99);
        assertEquals(0, valley.getVehSpeedKph());
        assertEquals(Gear.P, valley.getGear());
        assertEquals(800, valley.getEngRpm());
    }

    @Test
    public void invalidWindow_emitsInvalidSpeedFrames() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);

        // 第 600 帧进入 600-700 非法数据窗口
        for (int i = 0; i < 600; i++) {
            scheduler.tick();
        }
        VehicleState invalid = listener.states.get(599);
        assertEquals(600L, invalid.getSequence());
        assertEquals(255, invalid.getVehSpeedKph()); // 超出 200 上限
        assertEquals(9999, invalid.getEngRpm());
        assertEquals(DataValidity.INVALID_SPEED, invalid.getValidity());
        assertEquals(DataStatus.INVALID, invalid.getDataStatus());
    }

    @Test
    public void silentWindow_reportsNoData_thenResumesConnected() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        listener.statuses.clear();

        // 推进到第 699 帧（seq=699，仍在非法数据窗口内，无状态变更回调）
        for (int i = 0; i < 699; i++) {
            scheduler.tick();
        }
        int statesBeforeSilence = listener.states.size();
        assertEquals(0, listener.statuses.size());

        // 第 700 帧进入静默窗口：上报 NO_DATA，且不产生状态帧
        scheduler.tick();
        assertEquals(Collections.singletonList(DataSourceStatus.NO_DATA),
                listener.statuses);
        assertEquals(statesBeforeSilence, listener.states.size());

        // 静默窗口（seq 701..999）内不再产生任何回调
        for (int i = 0; i < 299; i++) {
            scheduler.tick();
        }
        assertEquals(statesBeforeSilence, listener.states.size());
        assertEquals(1, listener.statuses.size());

        // seq=1000 恢复正常：上报 CONNECTED 并继续产生帧
        scheduler.tick();
        assertEquals(2, listener.statuses.size());
        assertEquals(DataSourceStatus.CONNECTED,
                listener.statuses.get(listener.statuses.size() - 1));
        assertEquals(statesBeforeSilence + 1, listener.states.size());
        VehicleState resumed = listener.states.get(listener.states.size() - 1);
        assertEquals(1000L, resumed.getSequence());
        assertEquals(DataValidity.VALID, resumed.getValidity());
    }

    @Test
    public void start_whileAlreadyRunning_ignoresSecondListener() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener first = new RecordingListener();
        RecordingListener second = new RecordingListener();

        source.start(first);
        source.start(second);
        assertTrue(source.isRunning());
        assertEquals(0, second.states.size());
        assertEquals(0, second.statuses.size());

        scheduler.tick();
        assertEquals(1, first.states.size());
        assertEquals(0, second.states.size());
    }

    @Test
    public void stop_reportsStopped_andClearsRunningState() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        listener.statuses.clear();

        source.stop();

        assertFalse(source.isRunning());
        assertEquals(Collections.singletonList(DataSourceStatus.STOPPED),
                listener.statuses);
    }

    @Test
    public void factory_mockSourceType_createsMockDataSource() {
        VehicleDataSource dataSource = VehicleDataSourceFactory.create(
                null, SourceType.MOCK);
        assertSame(MockVehicleDataSource.class, dataSource.getClass());
        assertFalse(dataSource.isRunning());
    }

    @Test
    public void invalidWindow_lastFramePreservesRawBatteryAndClampsSoc() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        try {
            source.start(listener);
            for (int i = 0; i < 699; i++) scheduler.tick();
            VehicleState last = listener.states.get(698);
            assertEquals(699L, last.getSequence());
            assertEquals(100, last.getSoc());
            assertEquals(Float.valueOf(150f), last.getEvBatteryLevel());
            assertEquals(Float.valueOf(-999f), last.getEngineCoolantTemp());
            assertEquals(DataStatus.INVALID, last.getDataStatus());
        } finally {
            source.stop();
        }
    }

    @Test
    public void stop_twiceEmitsStoppedOnceAndDropsAlreadyQueuedNormalFrame() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        scheduler.tick();
        source.stop();
        source.stop();
        scheduler.tick(); // An executor task captured before shutdown can still be in flight.
        assertEquals(1, listener.states.size());
        assertEquals(java.util.Arrays.asList(DataSourceStatus.CONNECTED, DataSourceStatus.STOPPED),
                listener.statuses);
        assertFalse(source.isRunning());
    }

    @Test
    public void stop_beforeQueuedSilenceTransitionDoesNotDereferenceClearedListener() {
        ControllableScheduler scheduler = new ControllableScheduler();
        MockVehicleDataSource source = new MockVehicleDataSource(scheduler.scheduler());
        RecordingListener listener = new RecordingListener();
        source.start(listener);
        for (int i = 0; i < 699; i++) scheduler.tick();
        source.stop();
        scheduler.tick(); // seq=700: same cancellation contract as an ordinary queued frame.
        assertEquals(699, listener.states.size());
        assertEquals(java.util.Arrays.asList(DataSourceStatus.CONNECTED, DataSourceStatus.STOPPED),
                listener.statuses);
    }
}

package com.example.carlauncher;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.os.Looper;
import android.widget.TextView;

import androidx.lifecycle.Lifecycle;
import androidx.test.core.app.ActivityScenario;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;

import org.junit.Test;
import org.junit.runner.RunWith;
import androidx.test.platform.app.InstrumentationRegistry;

import static org.junit.Assert.assertEquals;

/**
 * BroadcastLabActivity 的 Instrumentation 测试：
 * 电源广播接收与 onStop 时的反注册。
 */
@RunWith(AndroidJUnit4.class)
public class BroadcastLabActivityTest {

    private static void idleMainLooper() {
        InstrumentationRegistry.getInstrumentation().waitForIdleSync();
    }

    @Test
    public void powerBroadcasts_updateStatusText() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            scenario.onActivity(activity -> {
                assertEquals("Waiting for power broadcast",
                        text(activity));
            });

            scenario.onActivity(activity -> {
                dispatchPowerAction(activity, Intent.ACTION_POWER_CONNECTED);
                assertEquals("Power connected", text(activity));
                dispatchPowerAction(activity, Intent.ACTION_POWER_DISCONNECTED);
                assertEquals("Power disconnected", text(activity));
            });
        }
    }

    @Test
    public void receiver_isUnregisteredAfterStop() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            scenario.onActivity(activity -> assertEquals(true, receiverRegistered(activity)));
            scenario.moveToState(Lifecycle.State.CREATED);
            scenario.onActivity(activity -> assertEquals(false, receiverRegistered(activity)));
        }
    }

    private static void dispatchPowerAction(BroadcastLabActivity activity, String action) {
        try {
            java.lang.reflect.Field field = BroadcastLabActivity.class
                    .getDeclaredField("powerReceiver");
            field.setAccessible(true);
            ((BroadcastReceiver) field.get(activity)).onReceive(activity, new Intent(action));
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError(exception);
        }
    }

    @Test
    public void sameInstanceReturningToForeground_registersReceiverAgain() {
        try (ActivityScenario<BroadcastLabActivity> scenario =
                     ActivityScenario.launch(BroadcastLabActivity.class)) {
            java.util.concurrent.atomic.AtomicReference<BroadcastLabActivity> original =
                    new java.util.concurrent.atomic.AtomicReference<>();
            scenario.onActivity(original::set);
            scenario.moveToState(Lifecycle.State.CREATED);
            scenario.moveToState(Lifecycle.State.RESUMED);
            scenario.onActivity(activity -> {
                org.junit.Assert.assertSame(original.get(), activity);
                org.junit.Assert.assertTrue("onStart must register after the previous onStop",
                        receiverRegistered(activity));
                dispatchPowerAction(activity, Intent.ACTION_POWER_CONNECTED);
                assertEquals("Power connected", text(activity));
            });
        }
    }

    private static boolean receiverRegistered(BroadcastLabActivity activity) {
        try {
            java.lang.reflect.Field field = BroadcastLabActivity.class
                    .getDeclaredField("receiverRegistered");
            field.setAccessible(true);
            return field.getBoolean(activity);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError(exception);
        }
    }

    private static String text(BroadcastLabActivity activity) {
        return ((TextView) activity.findViewById(R.id.broadcastStatusText))
                .getText().toString();
    }
}

